# U110: the revised final's browser chain, one Playwright run at a time on port 5423, at most two workers.
$b = $PSScriptRoot
$specs = 'tests/e2e/dark-ink.spec.ts tests/e2e/engine.spec.ts tests/e2e/excerpts.spec.ts tests/e2e/microscope.spec.ts tests/e2e/modes-engraving.spec.ts tests/e2e/perf.spec.ts tests/e2e/score-fit-paths.spec.ts tests/e2e/score.arrange-race.spec.ts tests/e2e/score.countin.spec.ts tests/e2e/score.density.spec.ts tests/e2e/score.fill.spec.ts tests/e2e/score.fuzz.spec.ts tests/e2e/score.head-height.spec.ts tests/e2e/score.hearIt.spec.ts tests/e2e/score.hearbar.spec.ts tests/e2e/score.latch.spec.ts tests/e2e/score.layout.spec.ts tests/e2e/score.pickup-numbers.spec.ts tests/e2e/score.readahead.spec.ts tests/e2e/score.renderer.fuzz.spec.ts tests/e2e/score.rotate.spec.ts tests/e2e/score.screen.spec.ts tests/e2e/score.slide.spec.ts tests/e2e/score.slots.spec.ts tests/e2e/score.spec.ts tests/e2e/score.states.spec.ts tests/e2e/score.window-rule.spec.ts tests/e2e/today.spec.ts'
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$b\run-sweep.ps1" -Out 'build/u110/sweep-final2' -Grep 'u110 sweep' -Log 'sweep-final2.log'
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$b\run-e2e.ps1" -Config 'build/u110/playwright.u110-5423.config.ts' -Log 'e2e-final2.log' -Workers 2 -Specs $specs
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$b\run-e2e.ps1" -Config 'build/u110/playwright.u110-states-5423.config.ts' -Log 'states-final2.log' -Workers 1
Set-Content -Path (Join-Path $b 'chain-final2.exit') -Value 'done' -Encoding ascii
